lter mobile start\",\n\t\t\"knip\": \"knip\",\n\t\t\"start\": \"node apps/server/dist/index.mjs\",\n\t\t\"typecheck\": \"turbo run typecheck\",\n\t\t\"test\": \"turbo run test --concurrency=1\",\n\t\t\"test:coverage\": \"turbo run test:coverage --concurrency=1\",\n\t\t\"test:ci\": \"turbo run test:ci --concurrency=1\",\n\t\t\"test:e2e\": \"playwright test\",\n\t\t\"test:e2e:ui\": \"playwright test --ui\",\n\t\t\"pdf:translations\": \"pnpm --filter @reactive-resume/tooling pdf:translations\",\n\t\t\"lint\": \"vp lint --deny-warnings\",\n\t\t\"lint:fix\": \"vp lint --fix\",\n\t\t\"lint:agent\": \"vp lint --deny-warnings --format=agent\",\n\t\t\"format\": \"vp fmt --write\",\n\t\t\"format:check\": \"vp fmt --check\",\n\t\t\"test:cloudflare\": \"node tooling/cloudflare/smoke.mjs\"\n\t},\n\t\"devDependencies\": {\n\t\t\"@commitlint/cli\": \"^21.2.4\",\n\t\t\"@commitlint/config-conventional\": \"^21.2.4\",\n\t\t\"@dotenvx/dotenvx\": \"^2.38.2\",\n\t\t\"@playwright/test\": \"^1.64.1\",\n\t\t\"@reactive-resume/config\": \"workspace:*\",\n\t\t\"@shadcn/lint\": \"^0.2.3\",\n\t\t\"@testing-library/jest-dom\": \"^7.0.1\",\n\t\t\"@testing-library/react\": \"^16.3.3\",\n\t\t\"@testing-library/user-event\": \"^14.6.8\",\n\t\t\"@types/node\": \"catalog:\",\n\t\t\"@types/pg\": \"catalog:\",\n\t\t\"@vitest/coverage-v8\": \"5.0.5\",\n\t\t\"happy-dom\": \"^21.0.4\",\n\t\t\"knip\": \"^6.44.0\",\n\t\t\"lefthook\": \"^2.2.2\",\n\t\t\"pg\": \"catalog:\",\n\t\t\"react\": \"catalog:\",\n\t\t\"react-dom\": \"19.3.1\",\n\t\t\"turbo\": \"^2.11.10\",\n\t\t\"typescript\": \"catalog:\",\n\t\t\"vite-plus\": \"catalog:\",\n\t\t\"wrangler\": \"catalog:\"\n\t}\n}\n"
