      "path": "apps/server/src/http/app.ts",
      "content": "import type { ReadWebFile } from \"../static/web\";\nimport type { Http2Bindings, HttpBindings } from \"@hono/node-server\";\nimport type { Context } from \"hono\";\nimport { BlockList, isIP } from \"node:net\";\nimport { getConnInfo } from \"@hono/node-server/conninfo\";\nimport { Hono } from \"hono\";\nimport { bodyLimit } from \"hono/body-limit\";\nimport { compress } from \"hono/compress\";\nimport { prepareStagedBody, withStagedBody } from \"@reactive-resume/api/features/storage/transport\";\nimport { env } from \"@reactive-resume/env/server\";\nimport { prepareMcpDiscovery } from \"@reactive-resume/mcp\";\nimport { handleMcp } from \"../mcp/handler\";\nimport { handleOpenApi, handleOpenApiDocument } from \"../openapi/handler\";\nimport {\n\thandleAgentCatalog,\n\thandleApiCatalog,\n\thandleIntegrations,\n\thandleMcpServerCard,\n\thandleOAuthAuthorizationServer,\n\thandleOAuthProtectedResource,\n\thandleOpenIdConfiguration,\n\thandleOpenAiAppsChallenge,\n\thandleWellKnownFallback,\n} from \"../openapi/metadata\";\nimport { handleRpc } from \"../rpc/handler\";\nimport { handleAgentSkillArchive, handleAgentSkillsIndex } from \"../static/agent-skills\";\nimport { handleResumeCard } from \"../static/resume-card\";\nimport { serveResumePage } from \"../static/resume-page\";\nimport { handleSchemaJson } from \"../static/schema\";\nimport { handleLlms, handlePagesSitemap, handleResumesSitemap, handleRobots, handleSitemap } from \"../static/seo\";\nimport { handleUpload } from \"../static/uploads\";\nimport { handleWebApp, isProfilePath, isPublicResumePath, serveWebDistStatic } from \"../static/web\";\nimport { handleAlias } from \"./alias\";\nimport { handleAppleAppSiteAssociation, handleAndroidAssetLinks } from \"./app-links\";\nimport { handleAuth, handleOAuth } from \"./auth\";\nimport { handleCareerJobs } from \"./career-jobs\";\nimport { handleCustomDomain, handleTraefikProvider } from \"./custom-domain\";\nimport { handleHealth } from \"./health\";\nimport { handlePublicResumePdf } from \"./public-resume-pdf\";\nimport { handleResumePdfDownload } from \"./resume-pdf\";\n\ntype ServerEnvironment = { Bindings: HttpBindings | Http2Bindings };\n\nconst getTrustedClient = (context: Context<ServerEnvironment>, proxies: BlockList): string => {\n\ttry {\n\t\tconst address = getConnInfo(context).remote.address?.trim();\n\t\tif (!address || !isIP(address)) return \"unknown\";\n\t\tconst trusted = (ip: string) => proxies.check(ip, isIP(ip) === 4 ? \"ipv4\" : \"ipv6\");\n\t\tif (!trusted(address)) return address;\n\t\tconst forwarded = context.req.header(\"x-forwarded-for\");\n\t\tif (!forwarded) return address;\n\t\tconst chain = forwarded.split(\",\").map((ip) => ip.trim());\n\t\tif (chain.some((ip) => !isIP(ip))) return address;\n\t\tlet client = address;\n\t\tfor (const hop of chain.reverse()) {\n\t\t\tif (!trusted(client)) break;\n\t\t\tclient = hop;\n\t\t}\n\t\treturn client;\n\t} catch {\n\t\treturn \"unknown\";\n\t}\n};\n\ntype AppOptions = {\n\tserveStatic?: boolean;\n\ttrustedClient?: (request: Request) => string;\n\treadWebFile?: ReadWebFile;\n};\n\nexport function createApp(options: AppOptions = {}) {\n\tprepareMcpDiscovery();\n\tconst app = new Hono<ServerEnvironment>();\n\tconst proxies = new BlockList();\n\tfor (const range of env.TRUSTED_PROXIES) {\n\t\tconst [address, prefix] = range.split(\"/\");\n\t\tif (!address) continue;\n\t\tconst family = isIP(address) === 4 ? \"ipv4\" : \"ipv6\";\n\t\tif (prefix === undefined) proxies.addAddress(address, family);\n\t\telse proxies.addSubnet(address, Number(prefix), family);\n\t}\n\tconst client = (c: Context<ServerEnvironment>) => options.trustedClient?.(c.req.raw) ?? getTrustedClient(c, proxies);\n\n\t// The alias domain serves the same public pages; only the signed-in app's sections move to APP_URL.\n\tapp.use(\"*\", async (c, next) => handleAlias(c.req.raw) ?? (await next()));\n\t// A verified custom domain shows its primary resume; other hosts fall through.\n\tapp.use(\"*\", async (c, next) => (await handleCustomDomain(c.req.raw, client(c))) ?? next());\n\n\tapp.use(\"/auth/*\", async (c, next) => {\n\t\tawait next();\n\t\t// The app shell already carries a full policy that forbids framing; only add one where it's missing.\n\t\tif (!c.res.headers.has(\"Content-Security-Policy\")) c.header(\"Content-Security-Policy\", \"frame-ancestors 'none'\");\n\t\tc.header(\"X-Frame-Options\", \"DENY\");\n\t\tc.header(\"Referrer-Policy\", \"no-referrer\");\n\t\tc.header(\"Cache-Control\", \"no-store\");\n\t});\n\n\t// Caps every body parsed in memory before authentication or validation can reject it. RPC allows a batch of\n\t// agent attachments (the same 160 MiB ceiling as staged Vercel bodies); auth payloads are small JSON or forms.\n\tconst limitBody = (maxSize: number) =>\n\t\tbodyLimit({\n\t\t\tmaxSize,\n\t\t\tonError: (c) => {\n\t\t\t\tc.header(\"Cache-Control\", \"no-store\");\n\t\t\t\treturn c.json(\n\t\t\t\t\t{\n\t\t\t\t\t\tdefined: false,\n\t\t\t\t\t\tcode: \"PAYLOAD_TOO_LARGE\",\n\t\t\t\t\t\tstatus: 413,\n\t\t\t\t\t\tmessage: \"This request is too large. Use a smaller file and try again.\",\n\t\t\t\t\t},\n\t\t\t\t\t413,\n\t\t\t\t);\n\t\t\t},\n\t\t});\n\tapp.use(\"/api/openapi/*\", limitBody(40 * 1024 * 1024));\n\t// Hono's `/x/*` also matches `/x`, so each wildcard below covers its base path too.\n\tapp.use(\"/api/rpc/*\", limitBody(160 * 1024 * 1024));\n\tapp.use(\"/api/auth/*\", limitBody(1024 * 1024));\n\tapp.use(\"/api/storage/stage\", limitBody(64 * 1024));\n\n\tapp.post(\"/api/storage/stage\", (c) => prepareStagedBody(c.req.raw));\n\tapp.all(\"/api/rpc/*\", (c) => withStagedBody(c.req.raw, (request) => handleRpc(request, client(c))));\n\tapp.all(\"/api/openapi/*\", (c) => handleOpenApi(c.req.raw, client(c)));\n\tapp.get(\"/api/auth/oauth\", (c) => handleOAuth(c.req.raw));\n\tapp.all(\"/api/auth/*\", (c) => handleAuth(c.req.raw, client(c)));\n\tapp.get(\"/api/health\", () => handleHealth());\n\tapp.get(\"/api/internal/traefik\", (c) => handleTraefikProvider(c.req.raw));\n\tapp.on([\"GET\", \"POST\"], \"/api/career/run\", (c) => handleCareerJobs(c.req.raw));\n\tapp.get(\"/api/resumes/:username/:slug/pdf\", (c) =>\n\t\thandlePublicResumePdf(c.req.raw, c.req.param(\"username\"), c.req.param(\"slug\"), client(c)),\n\t);\n\tapp.get(\"/api/resumes/:id/pdf\", (c) => handleResumePdfDownload(c.req.raw, c.req.param(\"id\")));\n\t// Outside /api/resumes, which robots.txt keeps crawlers out of: link previews need to fetch these.\n\tapp.get(\"/cards/:username/:file{.+\\\\.png}\", (c) =>\n\t\thandleResumeCard(c.req.raw, c.req.param(\"username\"), c.req.param(\"file\").slice(0, -\".png\".length)),\n\t);\n\tapp.get(\"/api/uploads/*\", (c) => handleUpload(c.req.raw));\n\tapp.get(\"/uploads/*\", (c) => handleUpload(c.req.raw));\n\tapp.get(\"/schema.json\", () => handleSchemaJson());\n\tapp.get(\"/openapi.json\", () => handleOpenApiDocument());\n\tapp.all(\"/mcp/*\", (c) => handleMcp(c.req.raw, client(c)));\n\n\tapp.get(\"/.well-known/apple-app-site-association\", () => handleAppleAppSiteAssociation());\n\tapp.get(\"/.well-known/assetlinks.json\", () => handleAndroidAssetLinks());\n\tapp.get(\"/.well-known/integrations.json\", () => handleIntegrations());\n\t// Hono answers HEAD by running the GET route and dropping the body, headers kept.\n\tapp.get(\"/.well-known/api-catalog\", () => handleApiCatalog());\n\tapp.get(\"/.well-known/agent-skills/index.json\", () => handleAgentSkillsIndex());\n\tapp.get(\"/.well-known/agent-skills/:filename\", (c) => handleAgentSkillArchive(c.req.param(\"filename\")));\n\tapp.get(\"/.well-known/mcp/server-card.json\", () => handleMcpServerCard());\n\tapp.on(\"GET\", [\"/.well-known/ard.json\", \"/.well-known/ai-catalog.json\"], () => handleAgentCatalog());\n\tapp.get(\"/.well-known/oauth-authorization-server/*\", (c) => handleOAuthAuthorizationServer(c.req.raw));\n\tapp.get(\"/.well-known/openid-configuration\", (c) => handleOpenIdConfiguration(c.req.raw));\n\tapp.get(\"/.well-known/oauth-protected-resource/*\", () => handleOAuthProtectedResource());\n\tapp.get(\"/.well-known/openai-apps-challenge\", () => handleOpenAiAppsChallenge());\n\tapp.all(\"/.well-known/*\", () => handleWellKnownFallback());\n\n\tapp.get(\"/robots.txt\", () => handleRobots());\n\tapp.get(\"/sitemap.xml\", () => handleSitemap());\n\tapp.get(\"/sitemaps/pages.xml\", () => handlePagesSitemap());\n\tapp.get(\"/sitemaps/:page{resumes-[0-9]+\\\\.xml}\", (c) =>\n\t\thandleResumesSitemap(Number(c.req.param(\"page\").slice(\"resumes-\".length, -\".xml\".length))),\n\t);\n\tapp.get(\"/llms.txt\", () => handleLlms());\n\n\t// Compresses only the web app's files and HTML shells: every route registered above answers before reaching\n\t// it, so API, MCP, and upload streams are never buffered or re-encoded. Where a CDN serves the static files\n\t// (Vercel), it also compresses at its edge.\n\tif (options.serveStatic !== false) app.use(\"/*\", compress());\n\n\t// Must precede the static middleware: serveStatic resolves \"/\" to dist/index.html and would\n\t// return it verbatim, skipping the OpenGraph/Twitter/canonical/JSON-LD injection in handleWebApp.\n\t// An instance can show one resume at its root instead of the marketing home; the configuration alone picks it.\n\tconst rootResumeId = env.ROOT_RESUME_ID;\n\tapp.on(\"GET\", [\"/\", \"/index.html\"], (c) =>\n\t\trootResumeId\n\t\t\t? serveResumePage(c.req.raw, { id: rootResumeId }, client(c))\n\t\t\t: handleWebApp(c.req.raw, options.readWebFile),\n\t);\n\tif (rootResumeId)\n\t\tapp.post(\"/\", limitBody(16 * 1024), (c) => serveResumePage(c.req.raw, { id: rootResumeId }, client(c)));\n\tif (options.serveStatic !== false && serveWebDistStatic) app.use(\"/*\", serveWebDistStatic);\n\t// A resume's web page, rendered here, and its password form; files with the same shape of address were served\n\t// just above. `/<username>` is the account's primary resume, on every domain the app answers.\n\tapp.on([\"GET\", \"POST\"], \"/:username/:slug\", limitBody(16 * 1024), (c, next) =>\n\t\tisPublicResumePath(c.req.path)\n\t\t\t? serveResumePage(c.req.raw, { username: c.req.param(\"username\"), slug: c.req.param(\"slug\") }, client(c))\n\t\t\t: next(),\n\t);\n\tapp.on([\"GET\", \"POST\"], \"/:username\", limitBody(16 * 1024), (c, next) =>\n\t\tisProfilePath(c.req.path)\n\t\t\t? serveResumePage(c.req.raw, { username: c.req.param(\"username\"), primary: true }, client(c))\n\t\t\t: next(),\n\t);\n\tapp.get(\"/*\", (c) => handleWebApp(c.req.raw, options.readWebFile));\n\n\treturn app;\n}\n"
    },
    {
      "path": "apps/server/src/mcp/handler.ts",
      "content": "import type { McpServer } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nimport { randomUUID } from \"node:crypto\";\nimport { WebStandardStreamableHTTPServerTransport } from \"@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js\";\nimport { ORPCError } from \"@orpc/server\";\nimport { consumeMcpRequestLimit, consumeMcpUserLimit } from \"@reactive-resume/api/features/mcp/transport\";\nimport { getTrustedOrigins } from \"@reactive-resume/auth/trusted-origins\";\nimport { env } from \"@reactive-resume/env/server\";\nimport { AuthError, authenticateRequest } from \"./auth\";\nimport { createMcpServer } from \"./server\";\n\nconst TRUSTED_ORIGINS = getTrustedOrigins(env.APP_URL);\nconst responseHeaders = {\n\t\"Cache-Control\": \"no-store\",\n\t\"X-Content-Type-Options\": \"nosniff\",\n};\n\nfunction errorResponse(status: number, message: string, headers?: Record<string, string>) {\n\treturn Response.json(\n\t\t{ id: null, jsonrpc: \"2.0\", error: { code: -32603, message } },\n\t\t{ status, headers: { ...responseHeaders, ...headers } },\n\t);\n}\n\nexport async function handleMcp(request: Request, trustedClient = \"unknown\") {\n\tlet server: McpServer | undefined;\n\tlet transport: WebStandardStreamableHTTPServerTransport | undefined;\n\ttry {\n\t\tconst origin = request.headers.get(\"origin\");\n\t\tif (origin !== null && !TRUSTED_ORIGINS.includes(origin)) {\n\t\t\treturn errorResponse(403, \"Origin is not allowed. Use the configured application origin or a native MCP client.\");\n\t\t}\n\t\tif (request.method !== \"POST\") {\n\t\t\treturn errorResponse(405, \"This stateless MCP endpoint accepts POST requests.\", { Allow: \"POST\" });\n\t\t}\n\t\tawait consumeMcpRequestLimit(trustedClient);\n\t\tconst authentication = await authenticateRequest(request);\n\t\tawait consumeMcpUserLimit(authentication.user.id);\n\t\tconst resHeaders = new Headers(responseHeaders);\n\t\tserver = createMcpServer(request, authentication, trustedClient, resHeaders);\n\t\ttransport = new WebStandardStreamableHTTPServerTransport({\n\t\t\tenableJsonResponse: true,\n\t\t\t// Larger files use authenticated upload references rather than base64 in JSON-RPC.\n\t\t\tmaxRequestBodySize: 4 * 1024 * 1024,\n\t\t});\n\t\tawait server.connect(transport);\n\t\tconst response = await transport.handleRequest(request);\n\t\tconst headers = new Headers(response.headers);\n\t\tfor (const [key, value] of resHeaders) headers.set(key, value);\n\t\treturn new Response(response.body, { status: response.status, statusText: response.statusText, headers });\n\t} catch (error) {\n\t\tif (error instanceof AuthError) {\n\t\t\treturn errorResponse(401, \"Unauthorized\", {\n\t\t\t\t\"WWW-Authenticate\": `Bearer resource_metadata=\"${env.APP_URL}/.well-known/oauth-protected-resource\"`,\n\t\t\t});\n\t\t}\n\t\tif (error instanceof ORPCError && error.code === \"TOO_MANY_REQUESTS\") {\n\t\t\tconst reset = (error.data as { reset?: number } | undefined)?.reset;\n\t\t\treturn errorResponse(429, \"Too many MCP requests. Retry after the rate limit resets.\", {\n\t\t\t\t\"Retry-After\": String(reset ? Math.max(1, Math.ceil((reset - Date.now()) / 1000)) : 60),\n\t\t\t});\n\t\t}\n\t\tconst diagnosticId = randomUUID();\n\t\tconsole.error(\"[MCP] Request failed\", { diagnosticId, name: error instanceof Error ? error.name : \"Unknown\" });\n\t\treturn errorResponse(500, `MCP request failed. Retry or contact support with diagnostic ID ${diagnosticId}.`);\n\t} finally {\n\t\t// JSON responses are complete before handleRequest resolves; no standalone streams remain.\n\t\ttry {\n\t\t\tif (server) await server.close();\n\t\t\telse if (transport) await transport.close();\n\t\t} catch {\n\t\t\tconsole.error(\"[MCP] Transport cleanup failed\");\n\t\t}\n\t}\n}\n"
    },
    {
      "path": "apps/server/src/mcp/auth.ts",
      "content": "import { resolveAuthenticationFromRequestHeaders } from \"@reactive-resume/api/context\";\n\nexport class AuthError extends Error {\n\tconstructor() {\n\t\tsuper(\"Unauthorized\");\n\t}\n}\n\nexport async function authenticateRequest(request: Request) {\n\t// MCP accepts API keys and bearer tokens; share their priority and validation with its oRPC tools.\n\tconst headers = new Headers(request.headers);\n\theaders.delete(\"cookie\");\n\tconst authentication = await resolveAuthenticationFromRequestHeaders(headers);\n\tif (authentication) return authentication;\n\tthrow new AuthError();\n}\n"
    },
    {
      "path": "apps/server/src/mcp/server.ts",
      "content": "import type { RouterClient } from \"@orpc/server\";\nimport type { RequestAuthentication } from \"@reactive-resume/api/context\";\nimport { McpServer } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nimport { onError } from \"@orpc/client\";\nimport { createRouterClient } from \"@orpc/server\";\nimport {\n\tbuildMcpServerInfo,\n\tMCP_TOOL_NAME,\n\tMCP_ROUTER,\n\tregisterParityTools,\n\tregisterPrompts,\n\tregisterResources,\n\tregisterTools,\n\tregisterToolDiscovery,\n} from \"@reactive-resume/mcp\";\nimport { appVersion } from \"../app-version\";\nimport { getRequestLocale } from \"../rpc/locale\";\n\nfunction createRequestClient(\n\trequest: Request,\n\tauthentication: RequestAuthentication,\n\ttrustedClient: string,\n\tresHeaders: Headers,\n): RouterClient<typeof MCP_ROUTER> {\n\tconst reqHeaders = new Headers(request.headers);\n\treqHeaders.delete(\"cookie\");\n\treturn createRouterClient(MCP_ROUTER, {\n\t\tinterceptors: [\n\t\t\t(options) => {\n\t\t\t\trequest.signal.throwIfAborted();\n\t\t\t\treturn options.next({\n\t\t\t\t\t...options,\n\t\t\t\t\tsignal: options.signal ? AbortSignal.any([request.signal, options.signal]) : request.signal,\n\t\t\t\t});\n\t\t\t},\n\t\t\tonError((error) => {\n\t\t\t\tconsole.error(\"[MCP oRPC]\", { name: error instanceof Error ? error.name : \"Unknown\" });\n\t\t\t}),\n\t\t],\n\t\tcontext: () => ({\n\t\t\tlocale: getRequestLocale(request),\n\t\t\treqHeaders,\n\t\t\tresHeaders,\n\t\t\ttrustedClient,\n\t\t\tauthentication,\n\t\t}),\n\t});\n}\n\nexport function createMcpServer(\n\trequest: Request,\n\tauthentication: RequestAuthentication,\n\ttrustedClient: string,\n\tresHeaders: Headers,\n) {\n\tconst server = new McpServer(buildMcpServerInfo(appVersion), {\n\t\tinstructions: [\n\t\t\t\"Reactive Resume holds the user's resumes, cover letters and job applications.\",\n\t\t\t`Find resume IDs with \\`${MCP_TOOL_NAME.listResumes}\\` and read one with \\`${MCP_TOOL_NAME.getResume}\\`; the resume JSON Schema is the \\`resume://_meta/schema\\` resource.`,\n\t\t\t`Edit resume content with JSON Patch through \\`${MCP_TOOL_NAME.patchResume}\\`, and change a resume's name, slug, tags or public visibility with \\`${MCP_TOOL_NAME.updateResume}\\`.`,\n\t\t\t`Track job applications with the application tools, starting from \\`${MCP_TOOL_NAME.listApplications}\\`.`,\n\t\t\t`Get a short-lived PDF link with \\`${MCP_TOOL_NAME.downloadResumePdf}\\`; export cover letters with \\`${MCP_TOOL_NAME.exportCoverLetter}\\`.`,\n\t\t\t\"Tools named api_* expose the rest of the Reactive Resume API. Tools that involve passwords, API keys or AI provider keys return a link to finish in the app.\",\n\t\t].join(\" \"),\n\t});\n\n\tconst client = createRequestClient(request, authentication, trustedClient, resHeaders);\n\tconst headers = new Headers(request.headers);\n\theaders.delete(\"cookie\");\n\tregisterResources(server, client);\n\tregisterTools(server, client, headers, authentication);\n\tregisterParityTools(server, client, headers, {\n\t\tauthentication,\n\t\tresHeaders,\n\t\ttrustedClient,\n\t\tlocale: getRequestLocale(request),\n\t\tsignal: request.signal,\n\t});\n\tregisterPrompts(server, client);\n\tregisterToolDiscovery(server);\n\n\treturn server;\n}\n"
    },
    {
      "path": "packages/mcp/src/tools.ts",
      "content": "import type { McpServer } from \"@modelcontextprotocol/sdk/server/mcp.js\";\nimport type { CallToolResult } from \"@modelcontextprotocol/sdk/types.js\";\nimport type { RouterClient } from \"@orpc/server\";\nimport type { RequestAuthentication } from \"@reactive-resume/api/context\";\nimport type router from \"@reactive-resume/api/routers\";\nimport type z from \"zod\";\nimport { ORPCError } from \"@orpc/server\";\nimport { resolveUserFromRequestHeaders } from \"@reactive-resume/api/context\";\nimport { applicationDto } from \"@reactive-resume/api/dto/application\";\nimport { coverLetterDto } from \"@reactive-resume/api/dto/cover-letter\";\nimport { resumeDto } from \"@reactive-resume/api/dto/resume\";\nimport { createResumePdfDownloadUrl } from \"@reactive-resume/api/features/resume/export\";\nimport { env } from \"@reactive-resume/env/server\";\nimport { readMcpFile } from \"./files\";\nimport { MCP_TOOL_NAME as T } from \"./mcp-tool-names\";\nimport { getClientCall, json, text, withErrorHandling } from \"./results\";\nimport { TOOL_META } from \"./tool-meta\";\n\nfunction coerceFollowUpAt(input: Record<string, unknown>): Record<string, unknown> {\n\tif (!(\"followUpAt\" in input)) return input;\n\n\tconst followUpAt = input.followUpAt;\n\tif (followUpAt === undefined || followUpAt === null || followUpAt instanceof Date) return input;\n\n\treturn { ...input, followUpAt: new Date(String(followUpAt)) };\n}\n\nfunction buildResumeShareUrl(username: string, slug: string): string {\n\tconst base = env.APP_URL.replace(/\\/$/, \"\");\n\treturn `${base}/${encodeURIComponent(username)}/${encodeURIComponent(slug)}`;\n}\n\nfunction resumeShareUrlNotes(input: { isPublic: boolean; hasPassword: boolean }): string {\n\tconst lines = [\n\t\t\"Anyone can open this link without signing in only when the resume is public (`isPublic: true`).\",\n\t\tinput.isPublic\n\t\t\t? \"This resume is currently public.\"\n\t\t\t: \"This resume is currently private; the URL is still your canonical share link if you make it public later.\",\n\t];\n\tif (input.hasPassword)\n\t\tlines.push(\n\t\t\t\"Password protection is enabled in the web app; visitors may need that password before content is shown.\",\n\t\t);\n\treturn lines.join(\"\\n\");\n}\n\n/** Tools whose structured result is the procedure's own response; the router client validates their input. */\nconst DIRECT_TOOLS = {\n\t[T.listResumeTags]: \"resume.tags.list\",\n\t[T.getResumeStatistics]: \"resume.statistics.getById\",\n\t[T.readCoverLetter]: \"coverLetters.getById\",\n\t[T.createCoverLetter]: \"coverLetters.create\",\n\t[T.updateCoverLetter]: \"coverLetters.update\",\n\t[T.refreshCoverLetterStyle]: \"coverLetters.refreshStyle\",\n\t[T.duplicateCoverLetter]: \"coverLetters.duplicate\",\n\t[T.exportCoverLetter]: \"coverLetters.export\",\n\t[T.importCoverLetter]: \"coverLetters.import\",\n\t[T.readApplication]: \"applications.getById\",\n\t[T.listApplicationTags]: \"applications.tags\",\n\t[T.getApplicationStats]: \"applications.stats\",\n\t[T.addApplicationNote]: \"applications.addNote\",\n\t[T.addApplicationInterview]: \"applications.addInterview\",\n\t[T.updateApplicationInterview]: \"applications.updateInterview\",\n\t[T.updateApplicationTimelineEntry]: \"applications.updateTimelineEntry\",\n\t[T.deleteApplicationTimelineEntry]: \"applications.deleteTimelineEntry\",\n\t[T.bulkUpdateApplications]: \"applications.bulkUpdate\",\n\t[T.bulkDeleteApplications]: \"applications.bulkDelete\",\n\t[T.removeApplicationDocument]: \"applications.removeDocument\",\n\t[T.autofillApplicationFromJob]: \"applications.ai.autofill\",\n\t[T.scoreApplicationMatch]: \"applications.ai.matchScore\",\n\t[T.tailorResumeForApplication]: \"applications.ai.tailorResume\",\n\t[T.draftApplicationMessage]: \"applications.ai.draftMessage\",\n} as const;\n\ntype ToolName = keyof typeof TOOL_META;\ntype ToolHandler<K extends ToolName> = (\n\tparams: z.infer<(typeof TOOL_META)[K][\"inputSchema\"]>,\n) => Promise<CallToolResult>;\n\nexport function registerTools(\n\tserver: McpServer,\n\tclient: RouterClient<typeof router>,\n\trequestHeaders: Headers,\n\tauthentication?: RequestAuthentication,\n) {\n\tconst handlers: { [K in Exclude<ToolName, keyof typeof DIRECT_TOOLS>]: ToolHandler<K> } = {\n\t\t[T.listResumes]: withErrorHandling(\"listing resumes\", async (params) => {\n\t\t\tconst resumes = await client.resume.list(params);\n\t\t\treturn text(JSON.stringify(resumes, null, 2), {\n\t\t\t\titems: resumes,\n\t\t\t\tlimit: params.limit,\n\t\t\t\toffset: params.offset,\n\t\t\t\tnextOffset: resumes.length === params.limit ? params.offset + resumes.length : null,\n\t\t\t});\n\t\t}),\n\n\t\t[T.getResume]: withErrorHandling(\"getting resume\", async ({ id }) => {\n\t\t\tconst resume = await client.resume.getById({ id });\n\n\t\t\treturn text(JSON.stringify(resume.data, null, 2), resume);\n\t\t}),\n\n\t\t[T.downloadResumePdf]: withErrorHandling(\"creating PDF download URL\", async ({ id }) => {\n\t\t\tconst resume = await client.resume.getById({ id });\n\t\t\tconst user = authentication?.user ?? (await resolveUserFromRequestHeaders(requestHeaders));\n\t\t\tif (!user) throw new ORPCError(\"UNAUTHORIZED\");\n\n\t\t\tconst signedUrl = createResumePdfDownloadUrl({ resumeId: id, userId: user.id });\n\n\t\t\treturn json({\n\t\t\t\tresumeId: id,\n\t\t\t\tname: resume.name,\n\t\t\t\tdownloadUrl: signedUrl.url,\n\t\t\t\texpiresAt: signedUrl.expiresAt,\n\t\t\t\texpiresInSeconds: signedUrl.expiresInSeconds,\n\t\t\t\tcontentType: \"application/pdf\",\n\t\t\t});\n\t\t}),\n\n\t\t[T.createResume]: withErrorHandling(\"creating resume\", async (params) => {\n\t\t\tconst { name, slug, withSampleData } = params;\n\t\t\tconst id = await client.resume.create(params);\n\n\t\t\treturn text(\n\t\t\t\t`Created resume \"${name}\" (ID: ${id}) ${slug ? `with slug \"${slug}\"` : \"with a generated address\"}.${withSampleData ? \" Pre-filled with sample data.\" : \"\"}\\n\\nNext steps: Use \\`${T.getResume}\\` to view it, or \\`${T.patchResume}\\` to start editing.`,\n\t\t\t\t{ id },\n\t\t\t);\n\t\t}),\n\n\t\t[T.importResume]: withErrorHandling(\"importing resume\", async ({ data }) => {\n\t\t\tconst parsed = resumeDto.import.input.safeParse({ data });\n\t\t\tif (!parsed.success)\n\t\t\t\treturn {\n\t\t\t\t\tisError: true,\n\t\t\t\t\tcontent: [\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\ttype: \"text\",\n\t\t\t\t\t\t\ttext: `Invalid ResumeData: ${parsed.error.message}\\n\\nHint: Ensure the JSON matches the schema at resume://_meta/schema`,\n\t\t\t\t\t\t},\n\t\t\t\t\t],\n\t\t\t\t};\n\n\t\t\tconst id = await client.resume.import(parsed.data);\n\n\t\t\treturn text(\n\t\t\t\t`Imported resume (ID: ${id}).\\n\\nNext steps: Use \\`${T.getResume}\\` to inspect metadata (name/slug were auto-generated), or \\`${T.updateResume}\\` / \\`${T.patchResume}\\` to adjust.`,\n\t\t\t\t{ id },\n\t\t\t);\n\t\t}),\n\n\t\t[T.duplicateResume]: withErrorHandling(\"duplicating resume\", async ({ id, name, slug, tags }) => {\n\t\t\tconst newId = await client.resume.duplicate({\n\t\t\t\tid,\n\t\t\t\t...(name ? { name } : {}),\n\t\t\t\t...(slug ? { slug } : {}),\n\t\t\t\t...(tags ? { tags } : {}),\n\t\t\t});\n\n\t\t\treturn text(\n\t\t\t\t`Duplicated resume${name ? ` as \"${name}\"` : \"\"} (ID: ${newId}) ${slug ? `with slug \"${slug}\"` : \"with a generated address\"}.\\n\\nNext steps: Use \\`${T.getResume}\\` to view it, or \\`${T.patchResume}\\` to customize.`,\n\t\t\t\t{ id: newId },\n\t\t\t);\n\t\t}),\n\n\t\t[T.patchResume]: withErrorHandling(\"patching resume\", async (params) => {\n\t\t\tconst { operations } = params;\n\t\t\tconst resume = await client.resume.patch(resumeDto.patch.input.parse(params));\n\t\t\tconst summary = operations.map((op) => `${op.op} ${op.path}`).join(\", \");\n\n\t\t\treturn text(`Applied ${operations.length} operation(s) to \"${resume.name}\": ${summary}`, resume);\n\t\t}),\n\n\t\t[T.updateResume]: withErrorHandling(\"updating resume\", async (params) => {\n\t\t\tconst input = resumeDto.update.input.parse(params);\n\t\t\tif (!Object.entries(input).some(([key, value]) => key !== \"id\" && key !== \"sessionId\" && value !== undefined))\n\t\t\t\tthrow new ORPCError(\"BAD_REQUEST\", { message: \"Provide at least one field to update.\" });\n\t\t\tconst resume = await client.resume.update(input);\n\n\t\t\tconst user = authentication?.user ?? (await resolveUserFromRequestHeaders(requestHeaders));\n\t\t\tconst username =\n\t\t\t\tuser && \"username\" in user && typeof (user as { username: unknown }).username === \"string\"\n\t\t\t\t\t? (user as { username: string }).username\n\t\t\t\t\t: \"\";\n\t\t\tconst shareUrl =\n\t\t\t\tusername !== \"\"\n\t\t\t\t\t? buildResumeShareUrl(username, resume.slug)\n\t\t\t\t\t: \"(could not build share URL: missing username on account)\";\n\n\t\t\tconst payload = {\n\t\t\t\tid: resume.id,\n\t\t\t\tname: resume.name,\n\t\t\t\tslug: resume.slug,\n\t\t\t\ttags: resume.tags,\n\t\t\t\tisPublic: resume.isPublic,\n\t\t\t\thasPassword: resume.hasPassword,\n\t\t\t\tshareUrl,\n\t\t\t};\n\n\t\t\treturn text(\n\t\t\t\t[\n\t\t\t\t\tJSON.stringify(payload, null, 2),\n\t\t\t\t\t\"\",\n\t\t\t\t\tresumeShareUrlNotes({ isPublic: resume.isPublic, hasPassword: resume.hasPassword }),\n\t\t\t\t].join(\"\\n\"),\n\t\t\t\tpayload,\n\t\t\t);\n\t\t}),\n\n\t\t[T.deleteResume]: withErrorHandling(\"deleting resume\", async ({ id }) => {\n\t\t\tawait client.resume.delete({ id });\n\n\t\t\treturn text(`Moved resume (${id}) to Trash. Restore it within 30 days.`);\n\t\t}),\n\n\t\t[T.lockResume]: withErrorHandling(\"locking resume\", async ({ id }) => {\n\t\t\tawait client.resume.setLocked({ id, isLocked: true });\n\n\t\t\treturn text(`Resume (${id}) is now locked. It cannot be edited, patched, or deleted until unlocked.`);\n\t\t}),\n\n\t\t[T.unlockResume]: withErrorHandling(\"unlocking resume\", async ({ id }) => {\n\t\t\tawait client.resume.setLocked({ id, isLocked: false });\n\n\t\t\treturn text(`Resume (${id}) is now unlocked. It can be edited, patched, and deleted.`);\n\t\t}),\n\n\t\t[T.listCoverLetters]: withErrorHandling(\"listing cover letters\", async (params) => {\n\t\t\tconst result = await client.coverLetters.list(coverLetterDto.list.input.parse(params));\n\t\t\treturn text(JSON.stringify(result, null, 2), {\n\t\t\t\t...result,\n\t\t\t\tlimit: params.limit,\n\t\t\t\toffset: params.offset,\n\t\t\t\tnextOffset: params.offset + result.items.length < result.total ? params.offset + result.items.length : null,\n\t\t\t});\n\t\t}),\n\n\t\t[T.deleteCoverLetter]: withErrorHandling(\"deleting cover letter\", async (params) => {\n\t\t\tawait client.coverLetters.delete(coverLetterDto.delete.input.parse(params));\n\t\t\treturn text(`Moved cover letter to Trash (${params.id}).`);\n\t\t}),\n\n\t\t[T.listApplications]: withErrorHandling(\"listing applications\", async (params) => {\n\t\t\tconst items = await client.applications.list(params);\n\t\t\treturn text(JSON.stringify(items, null, 2), {\n\t\t\t\titems,\n\t\t\t\tlimit: params.limit,\n\t\t\t\toffset: params.offset,\n\t\t\t\tnextOffset: items.length === params.limit ? params.offset + items.length : null,\n\t\t\t});\n\t\t}),\n\n\t\t[T.createApplication]: withErrorHandling(\"creating application\", async (params) => {\n\t\t\tconst id = await client.applications.create(applicationDto.create.input.parse(coerceFollowUpAt(params)));\n\t\t\treturn json({ id });\n\t\t}),\n\n\t\t[T.updateApplication]: withErrorHandling(\"updating application\", async (params) =>\n\t\t\tjson(await client.applications.update(applicationDto.update.input.parse(coerceFollowUpAt(params)))),\n\t\t),\n\n\t\t[T.deleteApplication]: withErrorHandling(\"deleting application\", async ({ id }) => {\n\t\t\tawait client.applications.delete({ id });\n\t\t\treturn text(`Deleted application (${id}).`);\n\t\t}),\n\n\t\t[T.importApplications]: withErrorHandling(\"importing applications\", async (params) =>\n\t\t\tjson(\n\t\t\t\tawait client.applications.import(\n\t\t\t\t\tapplicationDto.import.input.parse({ items: params.items.map(coerceFollowUpAt) }),\n\t\t\t\t),\n\t\t\t),\n\t\t),\n\n\t\t[T.attachApplicationDocument]: withErrorHandling(\"attaching application document\", async (params) => {\n\t\t\tconst user = authentication?.user ?? (await resolveUserFromRequestHeaders(requestHeaders));\n\t\t\tif (!user) throw new ORPCError(\"UNAUTHORIZED\");\n\t\t\tconst file = await readMcpFile(\n\t\t\t\t{\n\t\t\t\t\tname: params.fileName,\n\t\t\t\t\tcontentType: params.contentType,\n\t\t\t\t\t...(params.dataBase64 !== undefined\n\t\t\t\t\t\t? { dataBase64: params.dataBase64 }\n\t\t\t\t\t\t: { storagePath: params.storagePath }),\n\t\t\t\t},\n\t\t\t\tuser.id,\n\t\t\t);\n\t\t\tif ((await file.slice(0, 5).text()) !== \"%PDF-\")\n\t\t\t\tthrow new ORPCError(\"BAD_REQUEST\", { message: \"Supply a PDF file.\" });\n\t\t\treturn json(await client.applications.attachDocument({ id: params.id, kind: params.kind, file }));\n\t\t}),\n\t};\n\n\t// Register in TOOL_META order so the SDK's tools/list matches the static discovery list.\n\tfor (const [name, meta] of Object.entries(TOOL_META)) {\n\t\tconst path = DIRECT_TOOLS[name as keyof typeof DIRECT_TOOLS];\n\t\tconst handler =\n\t\t\thandlers[name as keyof typeof handlers] ??\n\t\t\twithErrorHandling(`calling ${name}`, async (params: unknown) => json(await getClientCall(client, path)(params)));\n\t\tserver.registerTool(name, meta, handler as never);\n\t}\n}\n"
    },
    {
      "path": "packages/mcp/src/tool-meta.ts",
      "content": "/**\n * Canonical tool metadata (title, description, inputSchema, annotations) declared once.\n * Consumed by both `registerTools` (raw Zod) and `buildMcpServerCard` (toJsonSchemaCompat).\n */\nimport type { BehaviorAnnotations } from \"./annotations\";\nimport z from \"zod\";\nimport { resumePatchOperationsSchema } from \"@reactive-resume/ai/tools/resume-tool-contracts\";\nimport { applicationDto } from \"@reactive-resume/api/dto/application\";\nimport { coverLetterDto } from \"@reactive-resume/api/dto/cover-letter\";\nimport { resumeDto } from \"@reactive-resume/api/dto/resume\";\nimport {\n\tapplicationStatusSchema,\n\tinterviewDetailsSchema,\n\tinterviewKindSchema,\n} from \"@reactive-resume/schema/applications/data\";\nimport { coverLetterDocumentSchema } from \"@reactive-resume/schema/cover-letter/data\";\nimport { READ_IDEMPOTENT, WRITE_DESTRUCTIVE_EXTERNAL, WRITE_NON_IDEMPOTENT, WRITE_DESTRUCTIVE } from \"./annotations\";\nimport { toWireObjectSchema, toWireSchema } from \"./contracts\";\nimport { MCP_TOOL_NAME as T } from \"./mcp-tool-names\";\n\n// Contracts remain derived from the allowlisted API procedures in parity.ts.\nexport const PARITY_TOOL_DESCRIPTIONS: Record<string, string> = {\n\t\"auth.exportData\":\n\t\t\"Export account documents and Career data. Private application profile is excluded from MCP results; export it in Settings → Profile.\",\n\t\"applications.lanes.get\":\n\t\t\"Read the account's ordered application stages and settings revision, including retired stages for history. Initializes missing default stages idempotently. Use returned lane IDs to select custom stages when creating or moving applications; category retains canonical workflow meaning.\",\n\t\"applications.lanes.create\":\n\t\t\"Add an owned application stage with a label, hex color and immutable canonical category. A Closed stage may preset its closure reason, for example no-response for Ghosted. Read stages first and send expectedRevision; stale changes return CONFLICT. Does not move or submit applications.\",\n\t\"applications.lanes.update\":\n\t\t\"Rename or recolor an owned application stage. Category and closure preset stay fixed; history keeps its semantic meaning. Read stages first and send expectedRevision; stale changes return CONFLICT.\",\n\t\"applications.lanes.reorder\":\n\t\t\"Replace the display order of all active owned application stages. Supply every active ID exactly once with expectedRevision. Reordering does not change application workflow milestones, submission dates or outcomes.\",\n\t\"applications.lanes.retire\":\n\t\t\"Retire a custom stage and move its current applications to an explicit active replacement with the same category and closure preset. Default system stages cannot be retired. Preserves applications, submitted documents and historical stage identities. Read stages first and send expectedRevision.\",\n\t\"applications.priorNoResponse\":\n\t\t\"Read at most ten owned applications with a current or recorded historical no-response outcome at the given company, matched conservatively by case and whitespace. Advisory evidence only: does not block, close or submit an application. Cleared outcomes from before outcome history was recorded cannot be reconstructed.\",\n\t\"documents.list\":\n\t\t\"List owned resumes and cover letters, optionally from Trash. Listing Trash also permanently purges documents older than 30 days and their owned files.\",\n\t\"aiProviders.list\":\n\t\t\"List saved AI providers with redacted credentials. When AI is server-managed, synchronize the account's managed provider record with server configuration. Does not contact an AI provider.\",\n\t\"aiProviders.test\":\n\t\t\"Test the saved provider/model connection server-side, then replace its saved test status and timestamp and enable or disable the connection based on the result.\",\n\t\"agent.threads.get\":\n\t\t\"Read an owned conversation, messages and attachments. If its active run is stale, clear the dead run claim and settle its streaming message state before returning. Does not start generation or call an AI provider.\",\n\t\"agent.threads.start\":\n\t\t\"Start a document, application, or general career conversation using a tested saved AI provider. For scope=document, choose exactly one resumeId or coverLetterId. For scope=application, provide applicationId. For scope=career, omit document and application IDs.\",\n\t\"career.suggestTargetRoles\":\n\t\t\"Requires recipientVersion from aiProviders.list, disclosed with provider/model/origin before explicit user approval. Changed configuration returns CONFLICT without transmission; refresh and reconfirm. Send explicitly selected resume and opted-in shared Knowledge to the named AI connection for unsaved editable target roles. Requires user context consent. Never uses suggestions in searches or schedules before review and save.\",\n\t\"career.profile\":\n\t\t\"Read the user's career preferences: target roles, locations, what matters, minimum base salary, office days, notice period, timezone and memory mode (ask, auto or off).\",\n\t\"career.saveProfile\":\n\t\t\"Replace the user's career profile. Read the existing profile first and provide all fields to preserve them; omitted fields reset to their defaults.\",\n\t\"career.facts\":\n\t\t\"List career facts with their source and status. A null applicationId selects shared career memory; an applicationId selects that application's available memory. Optionally filter by query.\",\n\t\"career.saveFact\":\n\t\t\"Save an evidence-backed career fact with its original source and quote. Use applicationId for application-specific memory or null for shared career memory. Source ownership and scope are validated by the service.\",\n\t\"career.updateFact\":\n\t\t\"Correct a saved fact's text (the original is kept in its revisions), switch whether the coach uses it, or explicitly share it across the user's applications.\",\n\t\"career.forgetFact\":\n\t\t\"Erase a saved fact's text, source quotation and correction history, and unlink it from stories and saved items. A suppression marker prevents automatic recreation from the same source.\",\n\t\"career.stories\":\n\t\t\"List saved STARR stories and their supporting fact IDs for shared career context or an owned application.\",\n\t\"career.saveStory\":\n\t\t\"Create a STARR story, or replace an existing story by providing its id. Provide situation, task, action, result, reflection, and supporting fact IDs. Shared stories can only reference shared facts; the service validates ownership and scope.\",\n\t\"career.deleteStory\": \"Delete an owned STARR story. Its supporting facts remain available.\",\n\t\"career.savedItems\":\n\t\t\"Read what the coach saved for an application (fit checks, briefings, practice feedback, debriefs, answers, employer replies and offers), or one kind across applications. Outdated items were written before Knowledge or the application changed.\",\n\t\"career.deleteSavedItem\": \"Delete an owned saved item.\",\n\t\"career.applyReply\":\n\t\t\"Apply the chosen changes (by index) of a read employer message to its application: stage, follow-up, next-step note, or saving offer terms. This changes the application; it does not send an email.\",\n\t\"career.workspace\":\n\t\t\"Read an application's workspace: form answers, the submit checklist, questions to ask, evidence added from Fit, ticked plan rows and the pasted employer message.\",\n\t\"coverLetters.draft\":\n\t\t\"Write a draft of a cover letter's body with the user's AI provider, from the letter's linked resume and its application's job posting, using only facts from them. Returns the draft text as chunks in `events` to join in order; `truncated` is true past 500,000 characters. No letter content is saved; server-managed AI can synchronize its account provider record. Write the draft into the letter with `update_cover_letter`. Use variant `shorter` or `personal` with `previous` to revise an earlier draft.\",\n\t\"career.saveWorkspace\":\n\t\t\"Save parts of an application's workspace. Each key given replaces that whole key; keys left out keep their values.\",\n\t\"career.trackOpportunity\":\n\t\t\"Create an application at Saved from a discovered role, with its posting link and text and the preferences it matched.\",\n\t\"career.schedules\": \"List the user's career discovery, interview preparation, and follow-up schedules.\",\n\t\"career.saveSchedule\":\n\t\t\"Create a career schedule, or replace one by providing its id. Explicitly choose enabled and email preferences, nextRunAt, timezone, optional repeat interval, and any application, interview, or saved AI provider. Enabled schedules may later perform research or coaching and send configured notifications; saving does not run a job immediately.\",\n\t\"career.deleteSchedule\": \"Delete an owned career schedule and prevent its future scheduled runs.\",\n\t\"career.opportunities\":\n\t\t\"List discovered opportunities for review. Discovery results are suggestions; create a tracked application only when the user chooses one.\",\n\t\"career.dismissOpportunity\": \"Dismiss an owned discovered opportunity from the review queue.\",\n\t\"career.notifications\": \"Read the user's career notifications and their read status.\",\n\t\"career.markNotificationRead\": \"Mark an owned career notification as read.\",\n};\n\n// ponytail: shared schema fragment; exported so server-card can re-use without re-importing\nconst resumeIdSchema = z.string().min(1).describe(`Resume ID. Use \\`${T.listResumes}\\` to find valid IDs.`);\nconst applicationIdSchema = z\n\t.string()\n\t.min(1)\n\t.describe(`Application ID. Use \\`${T.listApplications}\\` to find valid IDs.`);\nconst applicationTimelineEntryIdSchema = z.string().min(1).describe(\"Timeline entry ID from an application response.\");\nconst applicationDocumentKindSchema = z.enum([\"resume\", \"cover-letter\"]);\nconst coverLetterIdSchema = z\n\t.string()\n\t.min(1)\n\t.describe(`Cover letter ID. Use \\